mkdir -p /tmp/sim && cat > /tmp/sim/s.py <<'E'
import sys
M=65536
prog=[]
for l in open(sys.argv[1]):
    l=l.split(';')[0].strip()
    if l: prog.append(l.split())
r=dict(a=0,b=0,c=0,d=0)
v=lambda x:r[x] if x in r else int(x)
pc=0;n=0;s=0
while 0<=pc<len(prog):
    i=prog[pc];op=i[0];n+=1;nx=pc+1
    if op=='set':r[i[1]]=v(i[2])%M
    elif op=='add':r[i[1]]=(r[i[1]]+v(i[2]))%M
    elif op=='mul':r[i[1]]=(r[i[1]]*v(i[2]))%M
    elif op=='mod':
        x=v(i[2])
        if x>0:r[i[1]]%=x
    elif op=='dec':r[i[1]]=max(0,r[i[1]]-1)
    elif op=='jnz':
        if v(i[1])!=0:nx=pc+v(i[2])
    elif op=='skp':
        if v(i[1])<v(i[2]):nx=pc+2
    elif op=='out':s+=v(i[1])
    pc=nx
print(s,n)
E
cd /tmp/<path> && python3 -I /tmp/sim/s.py prog.pw9 | tee answer.txt
